engineDefinitions.rawSource:
function makeShader(type, src){
  const s = gl.createShader(type);
  gl.shaderSource(s, src);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) || 'shader error');
  return s;
}

function initGL(){
  const prog = gl.createProgram();
  gl.attachShader(prog, makeShader(gl.VERTEX_SHADER, VERT));
  gl.attachShader(prog, makeShader(gl.FRAGMENT_SHADER, FRAG));
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog) || 'link error');
  gl.useProgram(prog);

  const buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  const loc = gl.getAttribLocation(prog, 'aPos');
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

  U = {};
  ['uRes','uDet','uTime','uC0','uC1','uC2','uC3','uGlowPos','uGlowCol','uGlow','uGlowSize','uDensity','uWarp','uGrain','uDrift','uPrecip','uShaft','uFog','uMilk','uDeck','uPuff','uNight','uHaze','uSquash','uTint','uRays','uRayLook','uHalo','uHaloLook','uLut','uLutAmt','uTexV','uCirA','uCirB','uSun','uPolar','uAureole','uWhiten','uPurple','uCrep','uLit','uTintHi','uFloorZ','uFloorH','uDogs','uCorona','uAlpha']
    .forEach(n => { U[n] = gl.getUniformLocation(prog, n); });

  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);   // crossfade compositing

  /* color LUT texture on unit 1 — identity until an owner grade lands.
     NPOT strip (1089×33): CLAMP_TO_EDGE + LINEAR, no mips (WebGL1 rule). */
  const lutTex = gl.createTexture();
  gl.activeTexture(gl.TEXTURE1);
  gl.bindTexture(gl.TEXTURE_2D, lutTex);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1089, 33, 0, gl.RGBA, gl.UNSIGNED_BYTE, identityLutPixels());
  gl.uniform1i(U.uLut, 1);
  gl.activeTexture(gl.TEXTURE0);
  if (LUT_PNG) loadLut(lutTex);
}

function identityLutPixels(){
  const px = new Uint8Array(1089 * 33 * 4);
  for (let b = 0; b < 33; b++)
    for (let g = 0; g < 33; g++)
      for (let r = 0; r < 33; r++){
        const i = ((g * 1089) + b * 33 + r) * 4;
        px[i] = Math.round(r / 32 * 255);
        px[i + 1] = Math.round(g / 32 * 255);
        px[i + 2] = Math.round(b / 32 * 255);
        px[i + 3] = 255;
      }
  return px;
}

function loadLut(tex){
  const img = new Image();
  img.onload = () => {
    try {
      const c = document.createElement('canvas');
      c.width = 1089; c.height = 33;
      const ctx = c.getContext('2d');
      ctx.drawImage(img, 0, 0);
      lutData = ctx.getImageData(0, 0, 1089, 33).data;
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, c);
      gl.activeTexture(gl.TEXTURE0);
      tick();
    } catch (e) { toast('LUT failed to load'); }
  };
  img.src = LUT_PNG;
}

function lutJS(col){
  if (!lutData || state.lutAmt <= 0.001) return col;
  const lc = col.map(v => clamp(v, 0, 1));
  const samp = (r, g, sl) => {
    const x = sl * 33 + r * 32, y = g * 32;
    const x0 = Math.floor(x), y0 = Math.floor(y);
    const x1 = Math.min(x0 + 1, sl * 33 + 32), y1 = Math.min(y0 + 1, 32);
    const fx = x - x0, fy = y - y0;
    const p = (xx, yy, ch) => lutData[(yy * 1089 + xx) * 4 + ch] / 255;
    return [0, 1, 2].map(ch =>
      (p(x0, y0, ch) * (1 - fx) + p(x1, y0, ch) * fx) * (1 - fy)
      + (p(x0, y1, ch) * (1 - fx) + p(x1, y1, ch) * fx) * fy);
  };
  const b33 = lc[2] * 32;
  const s0 = Math.floor(b33), s1 = Math.min(s0 + 1, 32);
  const a = samp(lc[0], lc[1], s0), b = samp(lc[0], lc[1], s1);
  const fb = b33 - s0;
  return col.map((v, i) => v + (a[i] + (b[i] - a[i]) * fb - v) * state.lutAmt);
}

function resize(){
  const dpr = Math.min(window.devicePixelRatio || 1, 1.75);
  canvas.width = Math.round(innerWidth * dpr);
  canvas.height = Math.round(innerHeight * dpr);
  gl.viewport(0, 0, canvas.width, canvas.height);
}

function detUnit(w, h){
  const keep = w / Math.max(0.1, state.scene.aspect);          // the unit that keeps the composition in frame
  const unit = keep + (h - keep) * clamp(state.scene.crop, 0, 1);   // slide toward the height rule = crop a little
  return Math.max(1, Math.min(h, unit));
}

function cloudThinness(){
  const lo = state.cloudLow, mi = state.cloudMid, hi = state.cloudHigh;
  if (lo === null || mi === null || hi === null) return 0;
  const sum = lo + mi + hi;
  return sum > 20 ? clamp(hi / sum, 0, 1) : 0;
}

function deckChar(code){
  if (code >= 95)                  return { white: 0.95, dim: 0.60, tint: [0.92, 0.95, 1.05] };
  if ((code >= 71 && code <= 77) || code === 85 || code === 86)
                                   return { white: 0.95, dim: 1.05, tint: [0.98, 1.00, 1.04] };
  if (code >= 80)                  return { white: 0.92, dim: 0.82, tint: [0.94, 0.97, 1.05] };
  if (code >= 61)                  return { white: 0.92, dim: 0.80, tint: [0.93, 0.97, 1.06] };
  if (code >= 51)                  return { white: 0.90, dim: 0.90, tint: [0.96, 0.98, 1.03] };
  if (code === 45 || code === 48)  return { white: 0.90, dim: 0.97 };
  return { white: 0.85, dim: 1.0 };
}

function solarGeom(h){
  const ms = nowMs();
  const off = nowOffsetSec(ms);   // DST-correct AT the (possibly simulated) date
  const loc = new Date(ms + off * 1000);
  const yStart = Date.UTC(loc.getUTCFullYear(), 0, 1);
  const N = Math.floor((loc.getTime() - yStart) / 86400000) + 1;
  const g = 2 * Math.PI / 365 * (N - 1 + (h - 12) / 24);
  const eot = 229.18 * (0.000075 + 0.001868 * Math.cos(g) - 0.032077 * Math.sin(g)
            - 0.014615 * Math.cos(2 * g) - 0.040849 * Math.sin(2 * g));      // minutes
  const decl = 0.006918 - 0.399912 * Math.cos(g) + 0.070257 * Math.sin(g)
             - 0.006758 * Math.cos(2 * g) + 0.000907 * Math.sin(2 * g)
             - 0.002697 * Math.cos(3 * g) + 0.00148 * Math.sin(3 * g);       // radians
  const corr = eot + 4 * state.lon - 60 * (off / 3600);                      // minutes
  const ha = ((h * 60 + corr) / 4 - 180) * Math.PI / 180;
  const lat = state.lat * Math.PI / 180;
  const sinA = Math.sin(lat) * Math.sin(decl) + Math.cos(lat) * Math.cos(decl) * Math.cos(ha);
  /* half-day angle with the standard -0.833 deg refraction + solar-limb correction */
  const h0 = Math.acos(clamp(
    (Math.sin(-0.833 * Math.PI / 180) - Math.sin(lat) * Math.sin(decl))
      / (Math.cos(lat) * Math.cos(decl)), -1, 1));
  const noon = 12 - corr / 60;
  const half = h0 * 12 / Math.PI;
  return { sinA, rise: noon - half, set: noon + half, dayLen: clamp(2 * half, 0.02, 23.98) };
}

function moonIllum(){
  const jd = nowMs() / 86400000 + 2440587.5;
  const phase = (((jd - 2451550.1) / 29.530588853) % 1 + 1) % 1;
  return 0.5 * (1 - Math.cos(2 * Math.PI * phase));
}

function bodyY(elevDeg){
  return elevDeg >= 0 ? 0.10 + (elevDeg / 90) * 0.80
                      : 0.10 + elevDeg * 0.030;
}

function sunScreenPos(h, geo, sunElev){
  const R = ((geo.rise % 24) + 24) % 24;
  const x = ((h - R) % 24 + 24) % 24;
  let fx;
  if (x <= geo.dayLen) fx = x / Math.max(geo.dayLen, 0.02);
  else fx = (24 - x) < (x - geo.dayLen) ? 0 : 1;   // pre-dawn east, post-set west
  return [0.16 + 0.68 * fx, bodyY(sunElev)];
}

function skyGlow(h, geo){
  const R = ((geo.rise % 24) + 24) % 24;
  const x = ((h - R) % 24 + 24) % 24;
  const sunElev = Math.asin(clamp(geo.sinA, -1, 1)) * 180 / Math.PI;
  if (sunElev > -5){
    const e = clamp(geo.sinA, 0, 1);
    return {
      pos: sunScreenPos(h, geo, sunElev),
      col: lerp3([0.98, 0.74, 0.58], [1.0, 0.95, 0.86], smooth01(clamp(e * 1.35, 0, 1))),
      str: (0.26 + 0.66 * e) * smooth01((sunElev + 5) / 6),
      /* body metadata so the V2 path can recolor from the disk table */
      elevDeg: sunElev,
      isMoon: false,
      /* a low sun reads bigger and softer; tight and deliberate high up */
      size: 1 + 0.5 * Math.exp(-Math.pow(Math.max(0, sunElev) / 18, 2))
    };
  }
  const mAlt = SKY2.moonAltitudeDeg(msAtHour(h), state.lat, state.lon);
  const nf = clamp((x - geo.dayLen) / Math.max(24 - geo.dayLen, 0.02), 0, 1);
  return {
