    if (env.transmit != null) {
      dimMul = Math.max(0.8, Math.min(1.1, 0.75 + 0.45 * Math.min(1, env.transmit)));
    }
    if (env.snowDepthM != null && env.snowDepthM > 0.02) {
      dimMul *= 1 + Math.min(0.15, env.snowDepthM * 0.5);
    }
    return { thin: Math.min(1, thin), dimMul: dimMul, amtMul: amtMul };
  }

  /* PUBLIC: Koschmieder's relation — measured visibility → an aerosol
     optical depth estimate (extinction 3.912/vis over a ~1 km haze
     layer). 19 km hazy-clear ≈ 0.2, 5 km murk ≈ 0.8, fog clamps at 1.5. */
  function visibilityToAod(visM) {
    if (!(visM > 100)) return null;
    return Math.min(1.5, Math.max(0.02, 3.912 / visM * 1000));
  }

  /* PUBLIC: the glow blob's color — the sun's transmitted disk color
     through this atmosphere (same bake as the gradient, so the glow
     always agrees with the sky behind it). White-gold high sun, ember
     red at the horizon. The moon keeps the hue trend (orange moonrise)
     pulled toward the cool scotopic blue. */
  function glowColor(bodyElevDeg, aod, isMoon) {
    aod = Math.min(2, Math.max(0.02, aod || 0.12));
    let ai = 0;
    while (ai < AODS.length - 2 && AODS[ai + 1] < aod) ai++;
    const at = c01((Math.log(aod) - Math.log(AODS[ai])) / (Math.log(AODS[ai + 1]) - Math.log(AODS[ai])));
    const n = DISK.colors[0].length;
    const ef = Math.max(0, Math.min(n - 1.001, (bodyElevDeg - DISK.elevMin) / DISK.elevStep));
    const ei = Math.floor(ef), et = ef - ei;
    const col = [0, 0, 0];
    for (let c = 0; c < 3; c++) {
      const lo = DISK.colors[ai][ei][c] * (1 - et) + DISK.colors[ai][ei + 1][c] * et;
      const hi = DISK.colors[ai + 1][ei][c] * (1 - et) + DISK.colors[ai + 1][ei + 1][c] * et;
      col[c] = lo * (1 - at) + hi * at;
    }
    if (isMoon) {
      // pull toward the night design's cool blue; low moons stay warm
      const B = [0.72, 0.78, 0.98];
      for (let c = 0; c < 3; c++) col[c] = col[c] + (B[c] - col[c]) * 0.65;
    }
    return col;
  }

  /* moon topocentric elevation — matches tools/sky-sim/astro.js */
  function moonAltitudeDeg(ms, latDeg, lonDeg) {
    const D2R = Math.PI / 180;
    const d = ms / 86400000 + 2440587.5 - 2451545.0;
    const e = (23.4393 - 3.563e-7 * d) * D2R;
    const Lp = (218.316 + 13.176396 * d) * D2R;
    const M = (134.963 + 13.064993 * d) * D2R;
    const F = (93.272 + 13.229350 * d) * D2R;
    const lo = Lp + 6.289 * D2R * Math.sin(M);
    const la = 5.128 * D2R * Math.sin(F);
    const ra = Math.atan2(Math.sin(lo) * Math.cos(e) - Math.tan(la) * Math.sin(e), Math.cos(lo));
    const dec = Math.asin(Math.sin(la) * Math.cos(e) + Math.cos(la) * Math.sin(e) * Math.sin(lo));
    const gmst = (280.46061837 + 360.98564736629 * d) * D2R;
    const H = gmst + lonDeg * D2R - ra;
    const lat = latDeg * D2R;
    const sinA = Math.sin(lat) * Math.sin(dec) + Math.cos(lat) * Math.cos(dec) * Math.cos(H);
    return Math.asin(Math.max(-1, Math.min(1, sinA))) / D2R;
  }

  return { stops, cloudDeck, deckTuning, visibilityToAod, glowColor, moonAltitudeDeg, GRADE };
})()

function tzOffsetSec(tz, atMs){
  const now = Date.now();
  const key = tz + '|' + (atMs == null ? 'live' : Math.floor(atMs / 3600000));
  const hit = _tzMemo.get(key);
  if (hit && now - hit.at < TZ_MEMO_TTL_MS) return hit.off;
  try {
    const d = atMs == null ? new Date() : new Date(atMs);
    const loc = new Date(d.toLocaleString('en-US', { timeZone: tz }));
    const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
    const off = Math.round((loc - utc) / 60000) * 60;
    if (_tzMemo.size >= TZ_MEMO_MAX_KEYS) _tzMemo.clear();
    _tzMemo.set(key, { at: now, off });
    return off;
  } catch (e) { return null; }
}

function nowOffsetSec(atMs){
  const o = state.tz ? tzOffsetSec(state.tz, atMs) : null;
  return o === null ? state.utcOffset : o;
}

function nowMs(){
  if (!state.dateSim) return Date.now();
  const p = state.dateSim.split('-');
  let off = nowOffsetSec(), t = Date.now();
  for (let i = 0; i < 2; i++){
    const loc = new Date(Date.now() + off * 1000);
    t = Date.UTC(+p[0], +p[1] - 1, +p[2],
                 loc.getUTCHours(), loc.getUTCMinutes(), loc.getUTCSeconds()) - off * 1000;
    const o2 = nowOffsetSec(t);
    if (o2 === off) break;
    off = o2;
  }
  return t;
}

function localHour(){
  if (!state.live) return state.hourOverride;
  const d = new Date(Date.now() + nowOffsetSec() * 1000);
  return d.getUTCHours() + d.getUTCMinutes() / 60 + d.getUTCSeconds() / 3600;
}

function msAtHour(h){
  const base = nowMs();
  if (state.live) return base;
  const live = new Date(base + nowOffsetSec(base) * 1000);
  const liveH = live.getUTCHours() + live.getUTCMinutes() / 60;
  const delta = ((h - liveH) % 24 + 36) % 24 - 12;
  return base + delta * 3600e3;
}

function fmtHour(h){
  h = ((h % 24) + 24) % 24;
  const H = Math.floor(h);
  const M = Math.floor((h - H) * 60);
  let hh = H % 12; if (hh === 0) hh = 12;
  return hh + ':' + String(M).padStart(2, '0') + (H < 12 ? ' AM' : ' PM');
}

function turbidity(aodPhys){
  const tA = smooth01((aodPhys - 0.05) / 0.35);                    // 0.05 pristine → 0.40 thick haze
  const rh = state.humidity;
  const tH = rh === null ? 0 : 0.45 * smooth01((rh - 55) / 40);    // 55% dry → 95% soup
  return clamp(Math.max(tA, tH), 0, 1);
}

function seedFloats(key, n){
  const la = Math.round(state.lat * 10), lo = Math.round(state.lon * 10);
  let a = (Math.imul(key, 73856093) ^ Math.imul(la, 19349663) ^ Math.imul(lo, 83492791)) >>> 0;
  const out = [];
  for (let i = 0; i < n; i++){
    a = (a + 0x6D2B79F5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    out.push(((t ^ (t >>> 14)) >>> 0) / 4294967296);
  }
  return out;
}

function daySeed(){
  const ms = nowMs();
  const loc = new Date(ms + nowOffsetSec(ms) * 1000);
  const day = loc.getUTCFullYear() * 372 + loc.getUTCMonth() * 31 + loc.getUTCDate();
  return seedFloats(day, 4);   // 4 floats in [0,1): hidden clouds, crystal size, spare, spare
}

function monthSeed(){
  const ms = nowMs();
  const loc = new Date(ms + nowOffsetSec(ms) * 1000);
  return seedFloats(loc.getUTCFullYear() * 12 + loc.getUTCMonth() + 7, 1)[0];
}

function buildFrame(){
  const h = localHour();
  const geo = solarGeom(h);
  const wT = state.wTime, wC = state.wCond, wK = state.wTemp;

  /* 1 — the sky gradient. V2: the physical LUT (real sun elevation +
     moon + live aerosol) through the owner's grade. Legacy: the TOD
     keyframes warped by solar geometry. Either way the SAME downstream
     layers (condition, AQI, fog, cloud density) apply on top, and the
     crossfade machinery sees only the resulting cols. */
  const aodPhys = effAod();                         // physical estimate (halo gate needs it)
  const aodNow = dispAod(aodPhys);                  // fx: haze axis pinned pristine when off
  const sunElevDeg = Math.asin(clamp(geo.sinA, -1, 1)) * 180 / Math.PI;
  const seed = daySeed();   // this day's unobservables (see daySeed): read by the corona, the twilight fan, …
  let squashU = 1;   // gradient height compression (sunset)
  let cols;
  {
    const moonElev = SKY2.moonAltitudeDeg(msAtHour(h), state.lat, state.lon);
    cols = SKY2.stops(sunElevDeg, moonElev, moonIllum(), aodNow);
    /* sunset compression: as the sun dips below the horizon, the warm
       glow band sinks with it — a true HEIGHT compression (uSquash
       bends the gradient coordinate so the low stops span less screen),
       plus a soft color cascade that cools the leftover warmth aloft.
       Zero at sunset itself, full ≈ −4.5…−7°, gone by −11° so the
       tuned night gradient is never touched. */
    const dep = -sunElevDeg;
    const w = smooth01(dep / 4.5) * (1 - smooth01((dep - 7) / 4));
    squashU = 1 - 0.45 * w;
    if (w > 0.001){
      cols[1] = lerp3(cols[1], cols[0], 0.28 * w);
      cols[2] = lerp3(cols[2], cols[1], 0.35 * w);
    }
  }


  /* 3 — condition. V2: the physical cloud deck — a bright, slightly
     cool lid whose presence ramps CONTINUOUSLY with cloud cover (no
     chip cliff), whose luminance scales from the scene's own light
     (overcast nights stay dark), and whose zenith gently outshines the
     horizon (the CIE overcast trait). Legacy: the original mood
     transform, verbatim, for the A/B toggle. Fog/snow milk applies to
     both. */
  const code = effCode(), cloud = effCloud();
  const cp = condProfile(code);
  const lift = cp.lift * wC;

  let deckU = 0;   // the lid amount the shader's cloud-base mottle rides on
  let puffU = 0;   // cumulus amount: bright defined clumps (partly regime)
  let nightU = 0;  // additive night-cloud veil (dark V2 skies only)
  let hazeU = 0;   // atmospheric-perspective veil: textured white low band
  let densScale = 1;   // a clear sky wears wisps, not cloud banks
  {
    const covAmt = Math.pow(smooth01((cloud - 15) / 85), 2.0);
    const precip = code >= 51;                    // raining = a lid overhead
    let amt = (precip ? Math.max(covAmt, 0.85) : covAmt) * wC;
    const dk = deckChar(code);
    if (state.sim === null){
      /* live sky: the radiation + layer signals tune the deck — thin
         bright marine layers stay bluish-bright, genuinely dark decks
         darken, snowy ground bounces light back up. amtMul: a bright
         BROKEN sky (low diffuse fraction at high reported cover) is not
         a lid — the model's cover number alone can't tell the difference */
      const t = SKY2.deckTuning({
        diffuseFrac: state.diffuseFrac,
        transmit: state.skyTransmit,
        thinHigh: cloudThinness(),
        snowDepthM: state.snowDepth,
      });
      dk.thin = Math.max(dk.thin || 0, t.thin);
      dk.dim = (dk.dim != null ? dk.dim : 1) * t.dimMul;
      amt *= t.amtMul;
    }
    /* THE CODE CAPS THE LID (owner rule): cover says HOW MUCH cloud,
       the WMO code says WHAT KIND. Codes 0–2 are the model's own
       judgment that the sun is out — the lid cannot close, however
       high the cover number reads (SF "partly cloudy · 77%" was
       rendering as thin overcast). The surplus cover goes to the FIELD
       below: full density, and cumulus that never hands off to a lid.
       Overcast (3) and precip codes keep their full-range deck. */
    if (code <= 2) amt = Math.min(amt, 0.30);
    deckU = Math.min(amt, 0.75);   // the deck's own ceiling, mirrored
    /* cumulus rides a BELL over cover: rises for scattered skies, peaks
       through the broken range — and only hands off to the deck when a
       lid is actually possible (code ≥ 3); under sunny codes the puffs
       stay defined all the way up the cover range */
    const bell = code <= 2
      ? smooth01((cloud - 12) / 30)
      : smooth01((cloud - 12) / 30) * (1 - smooth01((cloud - 68) / 27));
    puffU = 1.0 * bell * wC * (1 - deckU);
    /* the field displaces the gradient to draw clouds — but a CLEAR sky
       shouldn't wear a cloud suit. After sunset the whole day's color
       range compresses into a narrow horizon band, and full-strength
       displacement across that cliff reads as a permanent cloud deck.
       Scale displacement with reported cover: 0.3× when clear, full by
       ~65% cover. (V2 only — legacy keeps its constant field.) */
    densScale = 0.3 + 0.7 * smooth01((cloud - 8) / 55);
    /* …but DEEP NIGHT gets its wisps back: the night gradient is the
       gentle floor ramp — banks are impossible there, and the drifting
       gray-blue night clouds are a beloved part of the design */
    densScale = Math.max(densScale, 0.8 * smooth01((-sunElevDeg - 12) / 6));
    /* night clouds are LIT clouds — an additive dim veil (the beloved
       navy wisps), fading in once the sun is truly down. Both puff and
       night scale with the grade's texture vibrancy. */
    const texV = SKY2.GRADE.textureVibrancy != null ? SKY2.GRADE.textureVibrancy : 1;
    puffU *= texV;
    nightU = 0.6 * smooth01((-sunElevDeg - 10) / 6) * wC * texV;
    /* atmospheric perspective (owner): the lower sky whitens/brightens
       with distance — a little even on a clear day, more under
       scattered/broken cover, damped once a full deck owns the scene
       (the CIE lid keeps zenith > horizon). Day only: the night floor
       stays dark. */
    hazeU = (0.12 + 0.30 * smooth01((cloud - 8) / 45) * (1 - 0.55 * deckU)
                  * (code <= 2 ? 0.5 : 1))   // the code says sun: less white wash
          * smooth01((sunElevDeg - 2) / 8) * wC;
    cols = SKY2.cloudDeck(cols, amt, dk);
    if (lift > 0.001) cols = cols.map(c => lerp3(c, MILKY, lift).map(v => clamp(v, 0, 1)));
  }

  /* 4 — air quality. V2: ordinary air is ALL physics — the AOD axis
     carries the haze and the wash contributes NOTHING below AQI 150.
     Genuinely smoky air (forest-fire territory) reads as LIGHT, not
     dirt: an ember warmth that lives where the sun is low — smoke
     sunrises and sunsets go red-gold — plus a slight dimming and blue
     loss at midday. The brown SMOKE lerp is gone from V2 (owner:
     "beautifying, not a brown multiplier"). Legacy keeps the original
     wash verbatim for the A/B. */
  const aq = smooth01(clamp((effAqi() - 150) / 250, 0, 1)) * wC;
  if (aq > 0.001){
    {
      /* the ember band: peaks at sunrise/sunset, gone by ~ +25° and
         below −9° (night smoke is just darkness; the mud guard owns
         it). SCREEN-blended so it GLOWS — red-gold light on the
         horizon, never a muddying lerp. Midday smoke is a pure
         neutral dim (the capped AOD axis already pales the blue). */
      const lowSun = Math.exp(-0.5 * Math.pow(sunElevDeg / 11, 2))
                   * smooth01((sunElevDeg + 9) / 7);
      const EMBER = [1.0, 0.40, 0.14];
      const ew = [0.05, 0.13, 0.30, 0.55];      // the ember hugs the horizon
      const dim = 1 - 0.10 * aq;
      cols = cols.map((c, i) => {
        const k = ew[i] * aq * lowSun;
        return c.map((v, j) => {
          const d = clamp(v * dim, 0, 1);
          return clamp(d + EMBER[j] * k * (1 - d), 0, 1);
        });
      });
    }
  }

  /* 4a — daytime warmth guard: with the sun well up, haze near the
     horizon reads WHITE (atmospheric perspective), never brown — the
     LUT's warm aerosol horizon is physically real but reads as dirt
     (owner rule: brown only in genuinely apocalyptic smoke, and even
     that is handled by the neutral noon dim + low-sun ember above).
     Any warm excess in a bright day stop becomes BRIGHTNESS: pulled to
     a slightly lifted neutral of its own luminance. Golden hour is
     exempt (the gate opens above ~10° sun); night belongs to the mud
     guard. V2 only. */
  {
    const highSun = smooth01((sunElevDeg - 10) / 12);
    if (highSun > 0.001){
      cols = cols.map(c => {
        const l = 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];
        const warm = Math.min(1, Math.max(0, c[0] - c[2] - 0.004) * 40);
        const t = highSun * warm;
        if (t < 0.001) return c;
        const w = Math.min(1, l * 1.04 + 0.02);
        return c.map(v => clamp(v + (w - v) * t, 0, 1));
      });
    }
  }

  /* 4b — skyglow: the place's own light scattered back down — why a
     Manhattan night horizon glows amber while a Wyoming one is ink.
     state.skyglow is measured per place from the Black Marble
     composite (fetchSkyglow); the strength dial scales the whole
     effect. Screen-blended POST-grade like the night floor — the mud
     guard kills warm night tones by design, and city glow is the one
     legitimately warm night light. A cloud lid AMPLIFIES it (the deck
     reflects the city back down), and lights ebb after midnight.
     V2 only; rides the crossfade through cols like everything else. */
  {
    const g = state.skyglow !== null ? state.skyglow : 0.35;  // unknown place: modest suburb
    const nightG = smooth01((-sunElevDeg - 6) / 8);           // civil dusk → full by −14°
    const hh = ((h % 24) + 24) % 24;
    const ebb = 1 - 0.25 * smooth01(Math.min((hh + 1) % 24, 12) / 3.5);  // lights out 23:00→02:30
    const glowN = g * state.skyglowStrength * nightG * (1 + 0.9 * deckU) * ebb;
    if (glowN > 0.001){
      const GC = [1.0, 0.80, 0.58];             // sodium-amber, slightly whitened
      const gw = [0, 0.10, 0.38, 1.0];          // a dome: horizon-weighted, zenith stays dark
      cols = cols.map((c, i) => {
        const k = glowN * gw[i] * 0.55;
        return c.map((v, j) => clamp(v + GC[j] * k * (1 - v), 0, 1));
      });
    }
  }

  /* cloud density: slider x (condition delta + real cloud cover), thickened by haze */
  const dens = clamp(state.density * (1 + wC * (cp.dens + 0.35 * cloud / 100)) * (1 + 0.35 * aq) * densScale, 0.05, 1.8);

  /* glow, faded by clouds & condition, gated by time influence;
     bad air dims the sun and turns it that eerie smoke-orange */
  const sg = skyGlow(h, geo);
  /* V2: the glow takes the sun's transmitted disk color from the same
     atmosphere bake as the gradient — white-gold high, ember at the
     horizon — so the blob and the sky behind it always agree */
  sg.col = SKY2.glowColor(sg.elevDeg, aodNow, sg.isMoon);
  /* §2.6 AEROSOL REDDENING (phenomena plan): the disk table reddens with
     the DISPLAY aerosol axis, which is compressed to keep the gradient
     blue — so a smoky or humid day's sun looked like a clean day's. The
     PHYSICAL excess over that axis, times the sun's air mass (Kasten–
     Young, capped), takes the blue out first (Ångström-like per-channel
     depths) and dims the disk: hazy sunsets go deep red earlier. Applied
     to the disk, the deck tint and the cirrus tint alike. Sun only. */
  let redF = [1, 1, 1];
  if (!sg.isMoon && state.cloudLit.red > 0){
    const e = Math.max(sg.elevDeg, 0.5);
    const amS = Math.min(8, 1 / (Math.sin(e * Math.PI / 180) + 0.15 * Math.pow(e + 3.885, -1.253)));
    const ex = Math.max(0, aodPhys - aodNow) * state.cloudLit.red;
    const K = [0.35, 0.5, 0.7];
    redF = K.map(k => Math.exp(-ex * amS * k));
    sg.col = sg.col.map((v, i) => v * redF[i]);
  }
  const glowMul = lerp(1, cp.glow, wC) * (1 - 0.65 * (cloud / 100) * wC);
  const glowStr = sg.str * glowMul * wT * 0.85 * (1 - 0.55 * aq);
  const glowCol = lerp3(sg.col, [1.0, 0.45, 0.20], 0.7 * aq);

  /* godrays: the beam fan wears the glow's gates (condition, clouds,
     air quality) but carries its OWN elevation shape — the glow's raw
     brightness collapses at low sun, exactly where rays read best.
     Full strength through the golden hour, about half at high noon,
     fading out as the disk crosses the horizon (the afterglow takes
     over). Some cloud gives the beams something to shine past — a
     dead-clear sky keeps a whisper. The moon throws quiet rays. */
  let raysU = 0;
  if (!sg.isMoon){   // godrays belong to the SUN only (owner) — the moon throws none
    const shape = smooth01((sg.elevDeg + 2) / 6)
                * (0.55 + 0.45 * Math.exp(-Math.pow(Math.max(0, sg.elevDeg - 6) / 26, 2)));
    const cloudB = 0.35 + 0.65 * smooth01((cloud - 8) / 30);
    raysU = state.rays.strength * shape * glowMul * wT * (1 - 0.55 * aq) * cloudB;
  }

  /* 5 — clumpy fog: shader mixes toward this milk, pooled in noise banks.
     Milk brightness follows ambient light so night fog is dim, not white */
  const fog = (code === 45 || code === 48 ? 0.72 : 0) * wC;
  const L1 = 0.299 * cols[1][0] + 0.587 * cols[1][1] + 0.114 * cols[1][2];
  const milkL = 0.30 + 0.80 * L1;
  let milk = MILKY.map(v => clamp(v * milkL, 0, 1));

  /* 5a — LOW-SUN CLOUD TINT: clouds are white — neutral, color-faithful
     projection screens — so at low sun they take the TRANSMITTED,
     Rayleigh-reddened beam while the sky beside them stays scattered
     blue. The tint color is the sun's transmitted disk color from the
     same atmosphere bake as the gradient (redder as the sun and the
     haze drop it); a luminance-preserving chromatic multiply keyed to
     the field's bright material. Fades in below ~+8°, hands off to the
     gray dip as the sun crosses the horizon; needs clouds to paint on. */
  let tintU = [1, 1, 1];
  {
    const amt = 0.35 * smooth01((8 - sunElevDeg) / 5)
              * (1 - smooth01(-sunElevDeg / 1.8))
              * smooth01((cloud - 10) / 30) * wC;
    if (amt > 0.001){
      const dc = SKY2.glowColor(sunElevDeg, aodNow, false).map((v, i) => v * redF[i]);
      const dl = Math.max(0.05, 0.299 * dc[0] + 0.587 * dc[1] + 0.114 * dc[2]);
      tintU = dc.map(v => 1 + (v / dl - 1) * amt);
    }
  }
  /* 5a′ — SPLIT TINT (phenomena plan — L&L §4.20): the earth's shadow
     rises after sunset, so low cloud goes gray while high cloud is still
     lit and colored. Shadow height at depression α is R(1 − cos α): a
     1.5 km deck is dark by ≈1.2° (the gray dip above), 10 km cirrus stays
     lit to ≈3.2°. The cirrus tint keeps the deck's ramp-in and holds on
     past the deck's hand-off; the strands wear it in their overlay color. */
  let tintHiU = [1, 1, 1];
  if (state.cloudLit.hiTint > 0){
    const amtH = 0.35 * state.cloudLit.hiTint * smooth01((8 - sunElevDeg) / 5)
               * (1 - smooth01((-sunElevDeg - 3.2) / 1.8)) * wC;
    if (amtH > 0.001){
      const dh = SKY2.glowColor(Math.max(sunElevDeg, -2), aodNow, false).map((v, i) => v * redF[i]);
      const dlh = Math.max(0.05, 0.299 * dh[0] + 0.587 * dh[1] + 0.114 * dh[2]);
      tintHiU = dh.map(v => 1 + (v / dlh - 1) * amtH);
    }
  }

  /* 5b — TWILIGHT AFTERGLOW (Lynch & Livingston): two acts keyed to
     solar depression, in reverse before sunrise for free.
     Act 1, the gray dip (≈0…−2.5°): sunset light reaches clouds by
     skimming the murky boundary layer — the cloud material goes dim,
     flat gray while the sky behind is still bright.
     Act 2, the re-illumination (≈−2.5…−5.5°, dead by −7°): the light
     path lifts above the murk — long, clean, strongly reddened — and
     the same clouds re-ignite in rose, MORE vivid than before sunset.
     Painted as an additive lift on the cloud field (the night veil's
     channel, rose-tinted milk), so it needs clouds to paint on; the
     veil's upward weighting sweeps it through the deck. All three
     carriers (milk, puff, night) are crossfade-wired frame params. */
  {
    const dep = -sunElevDeg;
    const dip = smooth01((dep + 0.5) / 1.5) * (1 - smooth01((dep - 2.0) / 1.0));
    const aglow = smooth01((dep - 2.2) / 1.3) * (1 - smooth01((dep - 5.5) / 1.7));
    if (dip > 0.001){
      const mL = 0.299 * milk[0] + 0.587 * milk[1] + 0.114 * milk[2];
      milk = milk.map(v => clamp((v + (mL - v) * 0.6 * dip) * (1 - 0.22 * dip), 0, 1));
      puffU *= 1 - 0.35 * dip;
    }
    if (aglow > 0.001){
      const k = aglow * smooth01((cloud - 5) / 35) * wC;   // needs clouds to paint on
      if (k > 0.001){
        /* the re-lit clouds wear a blend of rose and THE SKY'S OWN
           mid-horizon hue, at reduced strength — so they sit IN the
           dusk, tinted by it, instead of glowing white on top of it
           (owner: sunset clouds were a little too bright/white) */
        const h2 = cols[2];
        const hL = Math.max(0.05, 0.299 * h2[0] + 0.587 * h2[1] + 0.114 * h2[2]);
        const TINT = [1.0, 0.58, 0.52].map((v, i) =>
          clamp(v * 0.6 + (h2[i] / hL) * 0.9 * 0.4, 0, 1.0));
        milk = milk.map((v, i) => clamp(v * (1 - 0.45 * k) + TINT[i] * 0.50 * k, 0, 1));
        const tV = SKY2.GRADE.textureVibrancy != null ? SKY2.GRADE.textureVibrancy : 1;
        nightU = Math.max(nightU, 0.38 * k * tV * state.afterglow.lift);   // lift dial: owner tones the re-lit brightness
      }
    }
  }

  /* 6 — precipitation: rain veils, snow flecks, hail = fast bright flecks */
  let pRain = 0, pSnow = 0, pSpd = 1;
  if (code >= 51 && code <= 55){ pRain = 0.35; pSpd = 0.7; }
  else if (code === 56 || code === 57){ pRain = 0.30; pSnow = 0.25; pSpd = 0.7; }
  else if (code >= 61 && code <= 65){ pRain = 0.60; }
  else if (code === 66 || code === 67){ pRain = 0.50; pSnow = 0.30; }
  else if (code >= 71 && code <= 77){ pSnow = 0.70; }
  else if (code === 85 || code === 86){ pSnow = 0.85; pSpd = 1.3; }
  else if (code >= 80 && code <= 82){ pRain = 0.75; pSpd = 1.3; }
  else if (code >= 95){ pRain = 0.90; pSpd = 1.6; if (code >= 96) pSnow = 0.25; }
  const precip = [pRain * wC, pSnow * wC, pSpd];

  /* 22° solar halo — DEFAULT-ON by owner decree: the halo is present
     essentially whenever the sun is, and only dies when the sky is
     genuinely shut — near-solid overcast, a true lid, wet weather,
     dirty air, night. (The old "icy thin cloud character" gates scored
     a marine-layer SF partly at ~0.03 — invisible.) sunVis alone keeps
     it off at night and in the moon regime (moon halo: later). The
     aerosol gate reads the PHYSICAL estimate — the display axis is
     compressed and would never reach the threshold. Force pins to 100%
     for tuning: weather bypassed, the sun-up fade stays. */
  let haloU = 0, haloGate = 0;   // haloGate: the weather gate alone (the sundogs ride it too)
  {
    const sunVis = smooth01((sunElevDeg + 2) / 6);
    const band = 1 - smooth01((cloud - 75) / 20);          // full until 75% cover
    const deckG = 1 - smooth01((deckU - 0.30) / 0.30);     // sunny-code cap passes free
    const aodG = 1 - smooth01((aodPhys - 0.35) / 0.45);
    const wet = (fog > 0 || pRain + pSnow > 0) ? 0 : 1;
    haloGate = band * aodG * deckG * wet * wC * (1 - 0.55 * aq);
    haloU = state.halo.strength * sunVis * (state.halo.force ? 1 : haloGate);
  }

  /* SUNDOGS (phenomena plan — L&L §5.8): the plate-crystal separation
     D(h) = 2·asin(√(n² − sin²h) / (2 cos h)) − 60°, n = 1.31 — 21.8° at
     the horizon, ~25° at 20°, ~36° at 40°, impossible past ≈61° — mapped
     onto the halo's own angular scale (radius = 22°). Strongest at a low
     sun, fading as it climbs; the halo's weather gate, with a preference
     for real high cloud when the feed reports it. Sun only. */
  let dogsU = [0, 0, 0];
  if (!sg.isMoon && sunElevDeg > -1){
    const hD = Math.max(sunElevDeg, 0) * Math.PI / 180;
    const sh = Math.sin(hD), ch = Math.cos(hD);
    const arg = Math.sqrt(1.7161 - sh * sh) / (2 * ch);
    if (arg < 1){
      const D = 2 * Math.asin(arg) * 180 / Math.PI - 60;
      const perDeg = state.halo.radius / 22;
      const shape = smooth01((sunElevDeg + 1) / 3) * (1 - smooth01((sunElevDeg - 15) / 40));
      const ice = state.cloudHigh !== null ? 0.5 + 0.5 * smooth01((state.cloudHigh - 10) / 40) : 0.75;
      const gateD = state.dogs.force ? 1 : haloGate * ice;
      dogsU = [state.dogs.strength * shape * gateD, D * perDeg, state.dogs.tail * perDeg];
    }
  }

  /* CORONA (phenomena plan — L&L §4.13): needs a THIN cloud in front of
     the body — some cover but no lid, mid layer preferred when known,
     dry — and favors the moon (a brighter moon, a clearer corona); by
     day the sun's glare leaves a faint aureole. The ring's radius is the
     dial jittered ±25% by the day seed, standing in for drop size. */
  let coronaU = [0, state.corona.radius * state.halo.radius / 22, state.corona.purity];
  {
    const bodyUp = smooth01((sg.elevDeg - 2) / 5);
    const thinC = smooth01((cloud - 20) / 30) * (1 - smooth01((cloud - 78) / 12));   // some cloud, no lid
    const midC = state.cloudMid !== null ? 0.4 + 0.6 * smooth01((state.cloudMid - 10) / 40) : 0.7;
    const dryC = (fog > 0 || pRain + pSnow > 0) ? 0 : 1;
    const body = sg.isMoon ? (0.3 + 0.7 * moonIllum()) : 0.35;
    const gateC = state.corona.force ? 1 : thinC * (1 - deckU) * midC * dryC * wC;
    const rad = state.corona.radius * (0.75 + 0.5 * seed[3]) * state.halo.radius / 22;
    coronaU = [state.corona.strength * bodyUp * body * gateC, rad,
               state.corona.purity * (sg.isMoon ? 1 : 0.4)];
  }

  /* clear-sky plumbing (phenomena plan, step 0): turbidity + the day
     seed are computed for every frame and exposed in status; the
     POLARIZER BAND is their first consumer. The FRAG owns the geometry;
     the CPU owns the gates — daylight (a blue-sky effect: in by +2°,
     gone below −6°, where the LUT's own deep twilight zenith takes
     over), turbidity (haze depolarizes: a hazy day flattens the arc),
     no deck to polarize, the AQI wash, the weather influence. Force pins
     the dial value for tuning (the daylight fade stays). Sun only. */
  const turbU = turbidity(aodPhys);
  const sunU = sunScreenPos(h, geo, sunElevDeg).concat([sunElevDeg]);   // x, y, true altitude
  let polarU = 0;
  {
    const dayG = smooth01((sunElevDeg + 6) / 8);
    polarU = state.purity.force
      ? state.purity.polarizer * dayG
      : state.purity.polarizer * dayG * (1 - 0.85 * turbU) * (1 - deckU) * (1 - 0.5 * aq) * wC;
  }
  /* aureole (phenomena plan, step 1): the sun-side half of the purity
     map. Turbidity works the OTHER way here — haze feeds forward
     scattering, so a hazy day gets a stronger, WIDER aureole (base
     half-width = the dial, +22° at full turbidity, a little wider again
     at low sun where the beam crosses more air). Sun only; no deck to
     scatter in; the daylight fade shared with the band. Force pins the
     dial (pristine width). */
  let aureoleU = [0, state.purity.aureoleWidth];
  {
    const dayG = smooth01((sunElevDeg + 6) / 8);
    if (state.purity.force){
      aureoleU = [state.purity.aureole * dayG, state.purity.aureoleWidth];
    } else {
      const lowSun = 1 - smooth01(sunElevDeg / 30);
      aureoleU = [state.purity.aureole * dayG * (0.6 + 0.8 * turbU) * (1 - deckU) * wC,
                  state.purity.aureoleWidth + 22 * turbU + 6 * lowSun];
    }
  }
  /* horizon whitening (phenomena plan, step 1): uWhiten is the aerosol
     optical depth per air mass the FRAG saturates with. Turbidity IS the
     signal — a pristine day gets only a whisper (0.2 floor, so the dial
     reads on an ordinary day too), full haze the whole 0.29/air mass
     (the FRAG's soft horizon reads the air-mass curve at ~2°, ≈19.5
     air masses, so 0.29 there ≈ the old 0.15 × 38: saturated at the
     horizon line, ~30% at 30° up). Shares the daylight fade; no deck to
     whiten under. Force = dial at full turbidity. */
  let whitenU = 0;
  {
    const dayG = smooth01((sunElevDeg + 6) / 8);
    whitenU = state.purity.force
      ? 0.29 * state.purity.horizon * dayG
      : 0.29 * state.purity.horizon * (0.2 + 0.8 * turbU) * dayG * (1 - deckU) * wC;
  }
  /* clear-sky twilight (phenomena plan, step 2). PURPLE LIGHT: timed on
     the REAL sun (the book's clock: rises past −2.5°, full −4.5…−6°,
     gone by −8.5°), scaled by the month's stratospheric dust (monthSeed:
     ~a quarter of months have none, the rest graded), wanting an open
     twilight sky (cover, deck). CREPUSCULAR FAN: rides the purple gate
     (structural pairing) × the clouds that could be casting — real
     low/total cover as a hint plus the day seed for the ones beyond the
     horizon nobody can see. Force pins both dials (dust 1, casting 1). */
  const dep = -sunElevDeg;
  const purpW = smooth01((dep - 2.5) / 2.0) * (1 - smooth01((dep - 6.0) / 2.5));
  const dust = smooth01((monthSeed() - 0.25) / 0.55);
  let purpleU = [0, state.purity.purpleHeight, state.purity.purpleWidth];
  let crepU = 0;
  if (purpW > 0.001){
    const open = (1 - deckU) * (1 - 0.7 * smooth01((cloud - 30) / 50)) * wC;
    const casting = 0.5 * smooth01((seed[0] - 0.3) / 0.5) + 0.5 * smooth01((cloud - 15) / 45);
    if (state.purity.force){
      purpleU[0] = state.purity.purple * purpW;
      crepU = state.purity.crep * purpW;
    } else {
      purpleU[0] = state.purity.purple * purpW * dust * open;
      crepU = state.purity.crep * purpW * dust * open * casting;
    }
  }

  /* CLOUD LIGHTING gates (phenomena plan — §4.18–4.19, §2.6 airlight):
     thin/back-light are daylight rules that need cloud to act on; the
     airlight bias belongs to the low sun and shares the daylight fade. */
  let litU = [0, 0, 0];
  {
    const cl = state.cloudLit;
    const cloudy = 0.3 + 0.7 * smooth01((cloud - 10) / 40);
    const dayL = smooth01((sunElevDeg + 1) / 4);
    const lowSunL = 1 - smooth01(sunElevDeg / 12);
    litU = [cl.thin * dayL * cloudy * wC,
            cl.back * dayL * cloudy * wC,
            cl.airlight * lowSunL * smooth01((sunElevDeg + 6) / 8)];
  }

  /* NIGHT FLOOR colors (display sRGB) × the night gate: in from −6°, full
     by −12°, so twilight keeps its own colors and the floor owns the
     moonless small hours. Zenith darker than horizon, blue-leaning. */
  const nightG = smooth01((-sunElevDeg - 6) / 6);
  const ft = clamp(state.night.floor, 0, 1);
  const floorZ = lerp3([0.020, 0.028, 0.060], [0.090, 0.120, 0.290], ft).map(v => v * nightG);
  const floorH = lerp3([0.030, 0.042, 0.085], [0.125, 0.165, 0.340], ft).map(v => v * nightG);

  /* wind: clouds advect downwind; stronger wind = faster drift.
     Gated by the Weather influence; at 0 it keeps a fixed gentle heading. */
  const th = (state.windDir + 180) * Math.PI / 180;     // blowing toward (compass)
  let dx = lerp(0.86, Math.sin(th), wC);
  let dy = lerp(0.50, Math.cos(th), wC);
  const dn = Math.hypot(dx, dy) || 1;
  const wMag = lerp(1, 0.55 + 1.25 * smooth01(effWind() / 45), wC);
  const drift = [dx / dn * wMag, dy / dn * wMag];

  return { cols, dens, glowPos: sg.pos, glowCol, glowStr, glowSize: sg.size || 1,
           drift, precip, fog, milk,
           deck: deckU, puff: puffU, night: nightU, haze: hazeU, squash: squashU,
           tint: tintU, rays: raysU, halo: haloU,
           sun: sunU, polar: polarU, aureole: aureoleU, whiten: whitenU,
           purple: purpleU, crep: crepU, dust, turb: turbU, seed,
           lit: litU, tintHi: tintHiU, redF, floorZ, floorH, dogs: dogsU, corona: coronaU };
}

function rebaseFade(){
  if (!fadePrev || !lastTarget) return;
  fadeHeld.push({ f: lastTarget, a: smooth01(fadeP) });
  if (fadeHeld.length > FADE_HELD_MAX) fadePrev = fadeHeld.shift().f;
  fadeP = 0;
}

function frameDist(a, b){
  let d = 0;
  for (let i = 0; i < 4; i++)
    for (let j = 0; j < 3; j++) d += Math.abs(a.cols[i][j] - b.cols[i][j]);
  for (let j = 0; j < 3; j++)
    d += Math.abs(a.glowCol[j] - b.glowCol[j]) * 0.5 + Math.abs(a.precip[j] - b.precip[j]);
  for (let j = 0; j < 2; j++)
    d += Math.abs(a.glowPos[j] - b.glowPos[j]) * 2 + Math.abs(a.drift[j] - b.drift[j]);
  for (let j = 0; j < 3; j++) d += Math.abs(a.milk[j] - b.milk[j]) * 0.3
                                 + Math.abs(a.tint[j] - b.tint[j]) * 0.4;
  return d + Math.abs(a.dens - b.dens) + Math.abs(a.glowStr - b.glowStr) * 1.5
       + Math.abs(a.glowSize - b.glowSize) * 0.3
       + Math.abs(a.fog - b.fog) * 2 + Math.abs(a.deck - b.deck) * 0.8
       + Math.abs(a.puff - b.puff) * 0.8 + Math.abs(a.night - b.night) * 0.8
       + Math.abs(a.haze - b.haze) * 0.8 + Math.abs(a.squash - b.squash) * 0.5
       + Math.abs(a.rays - b.rays) * 0.5 + Math.abs(a.halo - b.halo) * 0.5
       + Math.abs(a.polar - b.polar) * 0.5 + Math.abs(a.aureole[0] - b.aureole[0]) * 0.5
       + Math.abs(a.whiten - b.whiten) * 3
       + Math.abs(a.purple[0] - b.purple[0]) * 0.8 + Math.abs(a.crep - b.crep) * 0.5
       + Math.abs(a.lit[0] - b.lit[0]) * 0.5 + Math.abs(a.lit[1] - b.lit[1]) * 0.5
       + Math.abs(a.tintHi[0] - b.tintHi[0]) * 0.4 + Math.abs(a.tintHi[2] - b.tintHi[2]) * 0.4
       + Math.abs(a.floorZ[2] - b.floorZ[2]) * 2
       + Math.abs(a.dogs[0] - b.dogs[0]) * 0.5 + Math.abs(a.corona[0] - b.corona[0]) * 0.5;
}

function drawParams(f, alpha){
  gl.uniform2f(U.uRes, canvas.width, canvas.height);
  gl.uniform1f(U.uDet, detUnit(canvas.width, canvas.height));
  gl.uniform1f(U.uTime, slowT);
  gl.uniform1f(U.uAlpha, alpha);
  gl.uniform3f(U.uC0, f.cols[0][0], f.cols[0][1], f.cols[0][2]);
  gl.uniform3f(U.uC1, f.cols[1][0], f.cols[1][1], f.cols[1][2]);
  gl.uniform3f(U.uC2, f.cols[2][0], f.cols[2][1], f.cols[2][2]);
  gl.uniform3f(U.uC3, f.cols[3][0], f.cols[3][1], f.cols[3][2]);
  gl.uniform2f(U.uGlowPos, f.glowPos[0], f.glowPos[1]);
  gl.uniform3f(U.uGlowCol, f.glowCol[0], f.glowCol[1], f.glowCol[2]);
  gl.uniform1f(U.uGlow, f.glowStr);
  gl.uniform1f(U.uGlowSize, f.glowSize);
  gl.uniform1f(U.uDensity, f.dens);
  gl.uniform1f(U.uWarp, state.flow);
  gl.uniform1f(U.uGrain, state.grain);
  gl.uniform2f(U.uDrift, f.drift[0], f.drift[1]);
  gl.uniform3f(U.uPrecip, f.precip[0], f.precip[1], f.precip[2]);
  gl.uniform3f(U.uShaft, state.shaftStr, state.shaftCov, state.shaftReach);
  gl.uniform1f(U.uFog, f.fog);
  gl.uniform3f(U.uMilk, f.milk[0], f.milk[1], f.milk[2]);
  gl.uniform1f(U.uDeck, f.deck);
  gl.uniform1f(U.uPuff, f.puff);
  gl.uniform1f(U.uNight, f.night);
  gl.uniform1f(U.uHaze, f.haze);
  gl.uniform1f(U.uSquash, f.squash);
  gl.uniform3f(U.uTint, f.tint[0], f.tint[1], f.tint[2]);
  gl.uniform1f(U.uRays, f.rays);
  gl.uniform2f(U.uRayLook, state.rays.scale, state.rays.falloff);
  gl.uniform1f(U.uHalo, f.halo);
  gl.uniform3f(U.uHaloLook, state.halo.radius, state.halo.dispersion, 1.0);
  gl.uniform1f(U.uLutAmt, state.lutAmt);
  /* grade-shipped texture vibrancy + cirrus look (state-driven, no fade) */
  gl.uniform1f(U.uTexV, SKY2.GRADE.textureVibrancy != null ? SKY2.GRADE.textureVibrancy : 1);
  const ci = state.cirrus;
  gl.uniform4f(U.uCirA, ci.angle * Math.PI / 180, ci.variance * Math.PI / 180, ci.fiber, ci.opacity);
  gl.uniform4f(U.uCirB, ci.cover, ci.evolve, ci.breakDepth, ci.grain);
  /* sun-relative sky geometry + the polarizer band (frame params) */
  gl.uniform3f(U.uSun, f.sun[0], f.sun[1], f.sun[2]);
  gl.uniform1f(U.uPolar, f.polar);
  gl.uniform2f(U.uAureole, f.aureole[0], f.aureole[1]);
  gl.uniform1f(U.uWhiten, f.whiten);
  gl.uniform3f(U.uPurple, f.purple[0], f.purple[1], f.purple[2]);
  gl.uniform2f(U.uCrep, f.crep, state.purity.crepScale);
  gl.uniform3f(U.uLit, f.lit[0], f.lit[1], f.lit[2]);
  gl.uniform3f(U.uTintHi, f.tintHi[0], f.tintHi[1], f.tintHi[2]);
  gl.uniform3f(U.uFloorZ, f.floorZ[0], f.floorZ[1], f.floorZ[2]);
  gl.uniform3f(U.uFloorH, f.floorH[0], f.floorH[1], f.floorH[2]);
  gl.uniform3f(U.uDogs, f.dogs[0], f.dogs[1], f.dogs[2]);
  gl.uniform3f(U.uCorona, f.corona[0], f.corona[1], f.corona[2]);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}

function drawScene(dt){
  const target = buildFrame();
  if (fadePrev === null && lastTarget && frameDist(target, lastTarget) > FADE_EPS){
    fadePrev = lastTarget;                 // freeze the outgoing sky
    fadeP = 0;
  }
  if (fadePrev){
    fadeP = Math.min(1, fadeP + (dt || 0) / FADE_DUR);
    drawParams(fadePrev, 1.0);             // old sky, still breathing
    for (const h of fadeHeld) drawParams(h.f, h.a);
    drawParams(target, smooth01(fadeP));   // new sky dissolving in over it
    if (fadeP >= 1){ fadePrev = null; fadeHeld = []; }
  } else {
    drawParams(target, 1.0);
  }
  lastTarget = cloneFrame(target);
}

function frame(now){
  if (now - last < FRAME_MIN_MS){ requestAnimationFrame(frame); return; }
  const dt = Math.min((now - last) / 1000, 0.1);
  last = now;
  slowT += dt * state.speed;                       // "1x" ~= one cloud-length per 80s
  /* custom time is not frozen: it keeps flowing at timeFlow × real
     time, so a chosen golden hour actually unfolds (agency request) */
  if (!state.live){
    state.hourOverride = ((state.hourOverride + dt * state.timeFlow / 3600) % 24 + 24) % 24;
  }
  drawScene(dt);
  requestAnimationFrame(frame);
}

function exportPNG(p){
  try {
    const maxRB = gl.getParameter(gl.MAX_RENDERBUFFER_SIZE);
    if (p.w > maxRB || p.h > maxRB) throw new Error('resolution exceeds this GPU\u2019s limit');

    /* render one frame into a resized backbuffer, read it, restore */
    const pw = canvas.width, ph = canvas.height;
    canvas.width = p.w; canvas.height = p.h;
    gl.viewport(0, 0, p.w, p.h);
    drawScene(0);
    const px = new Uint8Array(p.w * p.h * 4);
    gl.readPixels(0, 0, p.w, p.h, gl.RGBA, gl.UNSIGNED_BYTE, px);
    canvas.width = pw; canvas.height = ph;
    gl.viewport(0, 0, pw, ph);

    for (let i = 3; i < px.length; i += 4) px[i] = 255;   // force opaque

    /* GL reads bottom-up; flip rows while packing into a 2D canvas */
    const c2 = document.createElement('canvas');
    c2.width = p.w; c2.height = p.h;
    const ctx = c2.getContext('2d');
    const img = ctx.createImageData(p.w, p.h);
    const row = p.w * 4;
    for (let y = 0; y < p.h; y++){
      img.data.set(px.subarray((p.h - 1 - y) * row, (p.h - y) * row), y * row);
    }
    ctx.putImageData(img, 0, 0);

    const slugify = t => t.toLowerCase().normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    const who = slugify(activeScene ? activeScene.label : state.place);
    const name = 'hark-' + who + '-' + p.slug + '-' + p.w + 'x' + p.h + '.png';
    post({ type: 'png', name, data: c2.toDataURL('image/png').split(',')[1] });
  } catch (e) {
    post({ type: 'pngfail' });
    toast('Export failed \u2014 ' + (e.message || e));
  }
}

function localHourLiveSnapshot(){
  const d = new Date(Date.now() + nowOffsetSec() * 1000);
  return d.getUTCHours() + d.getUTCMinutes() / 60;
}

function clearScene(){
  if (activeScene === null) return;
  activeScene = null;
}

function applyScene(sc){
  state.lat = sc.lat; state.lon = sc.lon; state.place = sc.name; state.tz = sc.tz;
  state.sim = sc.sim;
  state.windSim = sc.wind != null ? sc.wind : null;
  state.aqiSim = sc.aqi != null ? sc.aqi : null;

  /* resolve the named hour against this place's actual sun today */
  const geo = solarGeom(12);
  const H = {
    sunrise: geo.rise + 0.2, morning: geo.rise + 2.5,
    noon: (geo.rise + geo.set) / 2, afternoon: 15.5,
    golden: geo.set - 0.9, sunset: geo.set - 0.2, dusk: geo.set + 0.5,
    night: 23.0, midnight: 0.15
  };
  const h = typeof sc.hour === 'number' ? sc.hour : H[sc.hour];
  state.live = false;
  state.hourOverride = ((h % 24) + 24) % 24;

  activeScene = sc;

  fetchWeather(true);
}

function pokeNative(){
  const n = performance.now();
  if (n - _pokeAt > 400){ _pokeAt = n; post({ type: 'poke' }); }
}

function saveSnapshot(){
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify({
      place: state.place, lat: state.lat, lon: state.lon, tz: state.tz,
      utcOffset: state.utcOffset,
      temp: state.temp, code: state.code, cloud: state.cloud,
      wind: state.wind, windDir: state.windDir, aqi: state.aqi,
      aod: state.aod, humidity: state.humidity,
      cloudLow: state.cloudLow, cloudMid: state.cloudMid, cloudHigh: state.cloudHigh,
      visibility: state.visibility, diffuseFrac: state.diffuseFrac,
      skyTransmit: state.skyTransmit, snowDepth: state.snowDepth,
      cape: state.cape, gusts: state.gusts, skyglow: state.skyglow
    }));
  } catch (e) { /* storage unavailable — skip */ }
}

function loadSnapshot(){
  try {
    const j = JSON.parse(localStorage.getItem(SAVE_KEY));
    if (j && typeof j.lat === 'number' && typeof j.lon === 'number'){
      Object.assign(state, j);
      state.haveWx = false;              // treat as stale until a fresh fetch lands
      /* the Black Marble composite is static — a snapshot value for this
         place is current; mark it so fetchSkyglow skips the tile fetch */
      if (state.skyglow != null) _glowKey = state.lat.toFixed(2) + ',' + state.lon.toFixed(2);
    }
  } catch (e) { /* first run or storage unavailable */ }
}

async function fetchWeather(reset){
  const url = 'https://api.open-meteo.com/v1/forecast'
    + '?latitude=' + state.lat + '&longitude=' + state.lon
    + '&current=temperature_2m,weather_code,cloud_cover,is_day,wind_speed_10m,wind_direction_10m,relative_humidity_2m,cloud_cover_low,cloud_cover_mid,cloud_cover_high,wind_gusts_10m'
    /* radiation/visibility/snow/cape aren't served via current= — take
       the current hour from hourly (forecast_hours starts at "now") */
    + '&hourly=visibility,direct_radiation,diffuse_radiation,shortwave_radiation,terrestrial_radiation,snow_depth,cape'
    + '&forecast_hours=2&timezone=auto';
  const aqUrl = 'https://air-quality-api.open-meteo.com/v1/air-quality'
    + '?latitude=' + state.lat + '&longitude=' + state.lon
    + '&current=us_aqi,aerosol_optical_depth';
  const aqP = fetch(aqUrl).then(r => r.ok ? r.json() : null).catch(() => null);
  try {
    const r = await fetch(url);
    if (!r.ok) throw new Error('http ' + r.status);
    const j = await r.json();
    state.temp = j.current.temperature_2m;
    state.code = j.current.weather_code;
    state.cloud = j.current.cloud_cover;
    state.wind = j.current.wind_speed_10m;
    state.windDir = j.current.wind_direction_10m;
    if (j.current.relative_humidity_2m != null) state.humidity = j.current.relative_humidity_2m;
    if (j.current.cloud_cover_low != null) state.cloudLow = j.current.cloud_cover_low;
    if (j.current.cloud_cover_mid != null) state.cloudMid = j.current.cloud_cover_mid;
    if (j.current.cloud_cover_high != null) state.cloudHigh = j.current.cloud_cover_high;
    if (j.current.wind_gusts_10m != null) state.gusts = j.current.wind_gusts_10m;
    const hh = j.hourly;
    if (hh && hh.time && hh.time.length){
      const pick = v => (v && v[0] != null) ? v[0] : null;    // index 0 = the current hour
      state.visibility = pick(hh.visibility);
      state.snowDepth = pick(hh.snow_depth);
      state.cape = pick(hh.cape);
      const dir = pick(hh.direct_radiation), dif = pick(hh.diffuse_radiation);
      const sw = pick(hh.shortwave_radiation), terr = pick(hh.terrestrial_radiation);
      state.diffuseFrac = (dir != null && dif != null && dir + dif > 20) ? dif / (dir + dif) : null;
      state.skyTransmit = (sw != null && terr != null && terr > 50)
        ? clamp(sw / (0.75 * terr), 0, 1.2) : null;
    }
    state.utcOffset = j.utc_offset_seconds;
    state.haveWx = true;
    state.updated = new Date();
  } catch (e) {
    const warn = reset || state.haveWx || !fetchWeather.warned;
    state.haveWx = false;
    if (reset){
      state.temp = 16; state.code = 2; state.cloud = 40;
      state.wind = 9; state.windDir = 250; state.aqi = 35; state.updated = null;
    }
    if (warn){
      toast('Live weather is unreachable — pick a condition chip to simulate');
      fetchWeather.warned = true;
    }
  }
  const aj = await aqP;
  if (aj && aj.current && aj.current.us_aqi != null) state.aqi = aj.current.us_aqi;
  if (aj && aj.current && aj.current.aerosol_optical_depth != null) state.aod = aj.current.aerosol_optical_depth;
  saveSnapshot();
  tick();
  fetchSkyglow();   // place-keyed, cached: usually a no-op
}

GLOW = {
  MW: 80, MH: 40, TILE: 512, FLOOR: 55,
  url: (row, col) => 'https://gibs.earthdata.nasa.gov/wmts/epsg4326/best/'
    + 'VIIRS_Black_Marble/default/2016-01-01/500m/6/' + row + '/' + col + '.png'
}

async function glowTileData(col, row){
  col = ((col % GLOW.MW) + GLOW.MW) % GLOW.MW;
  if (row < 0 || row >= GLOW.MH) return null;          // beyond the poles
  const r = await fetch(GLOW.url(row, col));
  if (!r.ok) throw new Error('tile http ' + r.status);
  const bmp = await createImageBitmap(await r.blob());
  const c = document.createElement('canvas');
  c.width = GLOW.TILE; c.height = GLOW.TILE;
  const ctx = c.getContext('2d');
  ctx.drawImage(bmp, 0, 0);
  return ctx.getImageData(0, 0, GLOW.TILE, GLOW.TILE).data;
}

async function fetchSkyglow(){
  const key = state.lat.toFixed(2) + ',' + state.lon.toFixed(2);
  if (key === _glowKey && state.skyglow !== null) return;
  _glowKey = key;
  try {
    const R = 60, kmLat = 111.32;
    const kmLon = 111.32 * Math.max(0.05, Math.cos(state.lat * Math.PI / 180));
    const dLat = R / kmLat, dLon = R / kmLon;
    const tX = lon => (lon + 180) / (360 / GLOW.MW);
    const tY = lat => (90 - lat) / (180 / GLOW.MH);
    /* the tiles the window touches (up to 4 at a seam) */
    const tiles = new Map();
    for (const la of [state.lat - dLat, state.lat + dLat])
      for (const lo of [state.lon - dLon, state.lon + dLon])
        tiles.set(Math.floor(tX(lo)) + ',' + Math.floor(tY(la)), null);
    for (const k of tiles.keys()){
      const cr = k.split(',');
      tiles.set(k, await glowTileData(+cr[0], +cr[1]));
    }
    /* distance-weighted mean of the above-terrain radiance */
    const N = 48;
    let wsum = 0, vsum = 0;
    for (let iy = 0; iy < N; iy++){
      for (let ix = 0; ix < N; ix++){
        const la = state.lat + dLat * (2 * (iy + 0.5) / N - 1);
        const lo = state.lon + dLon * (2 * (ix + 0.5) / N - 1);
        const dKm = Math.hypot((la - state.lat) * kmLat, (lo - state.lon) * kmLon);
        if (dKm > R) continue;
        const fx = tX(lo), fy = tY(la);
        const td = tiles.get(Math.floor(fx) + ',' + Math.floor(fy));
        if (!td) continue;
        const px = Math.min(GLOW.TILE - 1, Math.floor((fx - Math.floor(fx)) * GLOW.TILE));
        const py = Math.min(GLOW.TILE - 1, Math.floor((fy - Math.floor(fy)) * GLOW.TILE));
        const j = (py * GLOW.TILE + px) * 4;
        const lum = 0.299 * td[j] + 0.587 * td[j + 1] + 0.114 * td[j + 2];
        wsum += 1 / (1 + Math.pow(dKm / 12, 2));
        vsum += Math.max(0, lum - GLOW.FLOOR) / (1 + Math.pow(dKm / 12, 2));
      }
    }
    const mean = wsum ? vsum / wsum : 0;
    state.skyglow = Math.min(1, Math.pow(mean / 130, 0.6));
    saveSnapshot();
    tick();
  } catch (e) { /* offline or decode unavailable: keep snapshot value / fallback */ }
}

function offlineMatches(q){
  q = fold(q);
  const starts = [], within = [];
  for (const c of CITIES){
    const n = fold(c.name);
    if (n.startsWith(q)) starts.push(c);
    else if (n.includes(q)) within.push(c);
  }
  return starts.concat(within).slice(0, 6);
}

async function doSearch(q, token){
  /* built-in list answers instantly, even fully offline */
  const local = offlineMatches(q);
  if (local.length) post({ type: 'results', token, list: local });

  /* live geocoding refines when reachable */
  const url = 'https://geocoding-api.open-meteo.com/v1/search?name='
    + encodeURIComponent(q) + '&count=6&language=en&format=json';
  try {
    const r = await fetch(url);
    const j = await r.json();
    const net = (j.results || []).map(it => ({
      name: it.name || 'Somewhere',
      sub: [it.admin1, it.country_code].filter(Boolean).join(', '),
      lat: it.latitude, lon: it.longitude,
      tz: it.timezone || null
    }));
    const seen = new Set(net.map(x => fold(x.name) + '|' + x.sub.slice(-2).toLowerCase()));
    const merged = net.concat(
      local.filter(x => !seen.has(fold(x.name) + '|' + x.sub.toLowerCase()))
    ).slice(0, 6);
    post({ type: 'results', token, list: merged });
  } catch (e) {
    if (!local.length){
      post({ type: 'results', token, list: [] });
      toast('Search is offline — try a major city from the built-in list');
    }
  }
}

function selectPlace(it){
  clearScene();
  state.lat = it.lat; state.lon = it.lon;
  state.place = it.name;
  state.tz = it.tz || null;
  fetchWeather(true);
}

function nearestCity(lat, lon){
  let best = null, bd = 1e9;
  const k = Math.cos(lat * Math.PI / 180);
  for (const c of CITIES){
    const d = (c.lat - lat) ** 2 + ((c.lon - lon) * k) ** 2;
    if (d < bd){ bd = d; best = c; }
  }
  return Math.sqrt(bd) < 0.6 ? best.name : 'My location';
}

function applyGeoPosition(pos){
  state.lat = pos.coords.latitude;
  state.lon = pos.coords.longitude;
  state.place = nearestCity(state.lat, state.lon);
  try { state.tz = Intl.DateTimeFormat().resolvedOptions().timeZone || null; }
  catch (e) { state.tz = null; }
  fetchWeather(true);
}

function fadeBase(i){
  let c = fadePrev.cols[i];
  for (const h of fadeHeld) c = lerp3(c, h.f.cols[i], h.a);
  return c;
}

function tick(){
  const h = localHour();
  const f = lastTarget || buildFrame();
  const mixP = fadePrev ? smooth01(fadeP) : 1;
  /* lutJS mirrors the GPU grade so the pill dot and the glass
     light/dark switching see the same colors the screen shows */
  const col = i => {
    const c = lutJS(fadePrev ? lerp3(fadeBase(i), f.cols[i], mixP) : f.cols[i]);
    /* the FRAG's night floor (screen-lift, zenith→horizon) — the glass UI
       must switch on the colors the screen actually shows */
    const nf = lerp3(f.floorH, f.floorZ, i === 0 ? 1 : i === 3 ? 0 : (3 - i) / 3);
    return c.map((v, j) => nf[j] + v * (1 - nf[j]));
  };
  const c3 = col(3);
  /* bottom-weighted sky luminance: native flips the glass UI light/dark on it */
  const L = c => 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];
  const lum = 0.1 * L(col(0)) + 0.2 * L(col(1)) + 0.3 * L(col(2)) + 0.4 * L(c3);
  /* true day/night at the displayed hour, from real solar geometry */
  const geo = solarGeom(h);
  const sunR = ((geo.rise % 24) + 24) % 24;
  const isDay = (((h - sunR) % 24) + 24) % 24 < geo.dayLen;
  post({
    type: 'status',
    place: state.place,
    tempF: Math.round(state.temp * 9 / 5 + 32),
    cond: condText(effCode()),
    cloud: Math.round(effCloud()),
    mph: Math.round(effWind() * 0.621371),
    dir: compass(state.windDir),
    aqi: Math.round(effAqi()),
    hour: h,
    timeText: fmtHour(h),
    live: state.live,
    sim: state.sim === null ? -1 : state.sim,
    simActive: state.sim !== null || state.windSim !== null || state.aqiSim !== null
             || state.cloudSim !== null || state.aodSim !== null,
    online: state.haveWx,
    windKmh: effWind(),
    windAuto: state.windSim === null,
    aqiVal: effAqi(),
    aqiAuto: state.aqiSim === null,
    aodVal: effAod(),
    aodAuto: state.aodSim === null,
    cloudAuto: state.cloudSim === null,
    dateSim: state.dateSim || '',
    flow: state.timeFlow,
    scene: activeScene ? activeScene.label : '',
    dot: [c3[0], c3[1], c3[2]],
    lum,
    day: isDay,
    glow: state.skyglow === null ? -1 : state.skyglow,
    /* clear-sky plumbing readouts (phenomena plan, step 0) */
    turb: f.turb,
    seed: f.seed,
    sunAlt: f.sun[2],
    polar: f.polar,
    aureole: f.aureole,
    whiten: f.whiten,
    purple: f.purple[0],
    crep: f.crep,
    dust: f.dust,
    lit: f.lit,
    tintHi: f.tintHi,
    floorZ: f.floorZ,
    floorH: f.floorH,
    dogs: [f.dogs[0], f.dogs[1] / (state.halo.radius / 22)],          // strength, separation in degrees
    corona: [f.corona[0], f.corona[1] / (state.halo.radius / 22), f.corona[2]],   // strength, radius in degrees, purity
    redF: f.redF,
    glowCol: f.glowCol,
    /* scene scale: the detail unit as a share of the height (1 = landscape, tuned look) */
    det: canvas.height > 0 ? detUnit(canvas.width, canvas.height) / canvas.height : 1
  });
}
